// src/services/auth.js

import { jwtDecode } from "jwt-decode"; // Assurez-vous d'avoir installé 'jwt-decode' (npm install jwt-decode)

let navigateInstance = null;

export const setNavigateInstance = (navigate) => {
  navigateInstance = navigate;
};

// Fonction pour récupérer les tokens
const getTokens = () => {
  const accessToken =
    localStorage.getItem("access_token") ||
    sessionStorage.getItem("access_token");
  const refreshToken =
    localStorage.getItem("refresh_token") ||
    sessionStorage.getItem("refresh_token");
  return { accessToken, refreshToken };
};

// Fonction pour stocker les tokens
export const storeTokens = (access, refresh, rememberMe) => {
  if (rememberMe) {
    localStorage.setItem("access_token", access);
    localStorage.setItem("refresh_token", refresh);
    sessionStorage.removeItem("access_token"); // Nettoie sessionStorage si "se souvenir de moi" est activé
    sessionStorage.removeItem("refresh_token");
  } else {
    sessionStorage.setItem("access_token", access);
    sessionStorage.setItem("refresh_token", refresh);
    localStorage.removeItem("access_token"); // Nettoie localStorage si "se souvenir de moi" est désactivé
    localStorage.removeItem("refresh_token");
  }
};

// Fonction pour supprimer les tokens (déconnexion)
export const logout = () => {
  localStorage.removeItem("access_token");
  localStorage.removeItem("refresh_token");
  localStorage.removeItem("user_id"); // Supprime l'ID utilisateur
  sessionStorage.removeItem("access_token"); // Nettoie sessionStorage aussi
  sessionStorage.removeItem("refresh_token");

  if (navigateInstance) {
    navigateInstance("/login"); // Redirige vers la page de connexion
  }
};

/**
 * Effectue une requête API authentifiée.
 * Gère l'ajout du token d'authentification et la gestion des erreurs HTTP.
 * @param {string} url - L'URL de l'API.
 * @param {Object} options - Options de la requête fetch (méthode, corps, etc.).
 * @returns {Promise<Response>} - La réponse de l'API.
 * @throws {Error} - Lance une erreur si la requête échoue ou si la réponse n'est pas OK.
 */
export const apiRequest = async (url, options = {}) => {
  let { accessToken } = getTokens(); // Utilise getTokens

  // Si aucun token n'est disponible, l'utilisateur n'est pas connecté
  if (!accessToken) {
    if (navigateInstance) {
      navigateInstance("/login"); // Redirige vers la page de connexion
    }
    // Lance une erreur au lieu de retourner null
    throw new Error(
      "Aucun token d'accès disponible. Redirection vers la page de connexion."
    );
  }

  const headers = {
    "Content-Type": "application/json",
    ...options.headers,
    Authorization: `Bearer ${accessToken}`, // Inclut toujours l'en-tête d'autorisation si accessToken existe
  };

  try {
    let response = await fetch(url, {
      ...options,
      headers,
    });

    // Si le token d'accès est expiré (statut 401)
    if (response.status === 401) {
      console.log("Access token expired, attempting to refresh...");
      try {
        const newAccessToken = await refreshToken(); // Utilise la fonction refreshToken
        // Retente la requête avec le nouveau token
        headers["Authorization"] = `Bearer ${newAccessToken}`;
        response = await fetch(url, {
          ...options,
          headers,
        });
      } catch (refreshError) {
        console.error("Refresh token failed, forcing logout:", refreshError);
        // logout() est déjà appelée dans refreshToken en cas d'échec
        throw new Error(
          "Échec du rafraîchissement du token. Veuillez vous reconnecter."
        );
      }
    }

    // Si la réponse n'est pas OK (statut non-2xx), nous la considérons comme une erreur.
    if (!response.ok) {
      const errorText = await response.text();
      let errorData = { detail: `Erreur HTTP: ${response.status}` };
      try {
        errorData = JSON.parse(errorText);
      } catch (e) {
        errorData.detail = errorText || errorData.detail;
      }
      const error = new Error(
        errorData.detail || `Erreur API: ${response.status}`
      );
      error.response = response;
      error.data = errorData;
      throw error;
    }

    return response; // Retourne l'objet Response si tout est OK
  } catch (error) {
    console.error("Erreur de réseau ou de requête API:", error);
    throw error;
  }
};

export const login = async (username, password, rememberMe = false) => {
  // Ajout du paramètre rememberMe
  try {
    const response = await fetch("http://127.0.0.1:8000/api/auth/token/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ username, password }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.detail || "Échec de la connexion");
    }

    const data = await response.json();
    storeTokens(data.access, data.refresh, rememberMe); // Utilise storeTokens

    const decodedToken = jwtDecode(data.access);
    // Stocke user_id dans localStorage.
    localStorage.setItem("user_id", decodedToken.user_id);

    if (navigateInstance) {
      navigateInstance("/dashboard");
    }
    return true;
  } catch (error) {
    console.error("Erreur de connexion:", error);
    throw error;
  }
};

export const isAuthenticated = () => {
  const { accessToken } = getTokens(); // Utilise getTokens
  if (!accessToken) {
    return false;
  }
  try {
    const decodedToken = jwtDecode(accessToken); // Utilise accessToken de getTokens
    const currentTime = Date.now() / 1000;
    return decodedToken.exp > currentTime;
  } catch (error) {
    console.error("Erreur lors du décodage du token:", error);
    return false;
  }
};

// Fonction pour rafraîchir le token d'accès
export const refreshToken = async () => {
  const { refreshToken: currentRefreshToken } = getTokens(); // Récupère le refresh token

  if (!currentRefreshToken) {
    logout();
    throw new Error(
      "Aucun token de rafraîchissement disponible. L'utilisateur doit se reconnecter."
    );
  }

  try {
    const response = await fetch(
      "http://127.0.0.1:8000/api/auth/token/refresh/",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ refresh: currentRefreshToken }), // Utilise currentRefreshToken
      }
    );

    if (!response.ok) {
      logout();
      const errorData = await response.json();
      throw new Error(errorData.detail || "Échec du rafraîchissement du token");
    }

    const data = await response.json();
    // Préserve le choix "se souvenir de moi". Si refresh_token était dans localStorage, il y reste.
    const rememberMe = !!localStorage.getItem("refresh_token");
    storeTokens(data.access, data.refresh, rememberMe); // Utilise storeTokens
    return data.access;
  } catch (error) {
    console.error("Erreur lors du rafraîchissement du token:", error);
    logout();
    throw error;
  }
};
